#include <iostream>
using namespace std;
int main() {
    double fen;
    cin >> fen;
    int t = (int)fen / 10;
    switch (t) {
        case 10: cout << 'A'; break;
        case 9: cout << 'B'; break;
        case 8: cout << 'C'; break;
        case 7: cout << 'D'; break;
        case 6: cout << 'E'; break;
        default: cout << 'F';
    }
    return 0;
}
